dump(){ adb exec-out uiautomator dump /dev/stdout 2>/dev/null | python3 -c "
import sys,re; s=sys.stdin.read(); print([t for t in re.findall(r'text=\"([^\"]*)\"', s) if t])"; }
tap(){ adb exec-out uiautomator dump /dev/stdout 2>/dev/null | python3 -c "
import sys,re,subprocess; s=sys.stdin.read()
m=re.search(r'text=\"$1\"[^>]*bounds=\"\[(\d+),(\d+)\]\[(\d+),(\d+)\]\"', s)
x=(int(m[1])+int(m[3]))//2; y=(int(m[2])+int(m[4]))//2; subprocess.run(['adb','shell','input','tap',str(x),str(y)])"; sleep 2; }
ime(){ adb shell dumpsys window InputMethod 2>/dev/null | grep -c "isVisible=true"; }
hidekb(){ if [ "$(ime)" != "0" ]; then adb shell input keyevent 4; sleep 1.5; fi; echo "ime=$(ime)"; }
T(){ adb shell input keyevent 61; sleep 0.5; adb shell input text "$1"; sleep 0.5; }
